values
('de.grammar.complex_structures',1,'de','grammar','Komplexe Satzstrukturen','Satzstruktur und typische Fehler – Deutsch','{"explanation":"Im deutschen Hauptsatz steht das finite Verb typischerweise an Position zwei; im eingeleiteten Nebensatz steht es häufig am Ende. Trennbare Verben bilden im Hauptsatz oft eine Satzklammer. Perfekt und Präteritum sind nicht beliebig austauschbar: Gesprächssprache nutzt häufig das Perfekt, schriftliche Erzählung häufig das Präteritum.","examples":[{"text":"Heute analysiert der Scout den Spieler.","note":"Vorfeld besetzt; finites Verb bleibt an zweiter Stelle."},{"text":"Der Scout sagt, dass der Spieler heute trainiert.","note":"Im dass-Satz steht das finite Verb am Ende."},{"text":"Der Trainer hat den Spieler gestern beobachtet.","note":"Perfekt mit haben und Partizip II."}],"common_errors":["Das finite Verb im deutschen Hauptsatz nicht automatisch an die dritte Position setzen.","Nebensatzstellung nicht mit Hauptsatzstellung verwechseln.","Kasus nicht allein aus der Wortreihenfolge ableiten."],"learning_objectives":["Satzstruktur korrekt erkennen","Zeit- und Aspektformen kontextbezogen unterscheiden","Negation und Einschränkungen vollständig erhalten"],"review_questions":["Welche Information trägt die Verbform?","Welche Satzteile gehören zusammen?","Welche Bedeutung ändert sich bei anderer Wortstellung?"],"grammar_notes":["Beispiele sind original formuliert und illustrativ, keine vollständige Grammatik."]}'::jsonb,ARRAY['grammar','syntax','word order','tense','negation','sentence structure','scouting'],'intermediate','active','original_authored','messinho_linguistic_v2'),
('de.pragmatics.intent_register',1,'de','pragmatics','Gesprächsabsicht und Register','Höflichkeit, Unsicherheit und Gesprächsnuancen – Deutsch','{"explanation":"Unterschied zwischen wörtlicher Aussage, Höflichkeitsform und indirekter Absicht beachten. Modalpartikeln wie doch, eben, ja, wohl und eigentlich verändern Haltung und Gesprächston. Einschränkungen wie noch nicht, eher, teilweise und zwar...aber müssen erhalten bleiben.","examples":[{"text":"Er ist gut, aber noch nicht bereit.","intent":"positive Einschätzung mit klarer Einschränkung"},{"text":"Könntest du den Bericht bitte prüfen?","intent":"höfliche Bitte, kein Befehl"},{"text":"Das dürfte schwierig werden.","intent":"vorsichtige Prognose, keine Gewissheit"}],"common_errors":["Höfliche Bitte nicht als Befehl interpretieren.","Unsicherheit nicht in Gewissheit umwandeln.","Verneinung, Einschränkung und Kontrast nicht entfernen."],"learning_objectives":["Wörtliche Bedeutung und Gesprächsabsicht unterscheiden","Grad der Gewissheit bewahren","Register und Höflichkeit berücksichtigen"]}'::jsonb,ARRAY['pragmatics','politeness','intent','uncertainty','negation','register'],'advanced','active','original_authored','messinho_linguistic_v2'),
('de.lexicon.football_scouting',1,'de','lexicon','Fußball- und Scoutingterminologie','Fußballbegriffe im Kontext – Deutsch','{"explanation":"Scoutingbegriffe müssen im Fußballkontext interpretiert werden. Leistung ist nicht gleich Ergebnis; Potenzial ist keine sichere Prognose. Positionsbezeichnungen, Fuß, Pressingrolle und Datenmetriken benötigen Kontext und Bezugsgröße.","terms":[{"term":"Abschluss","meaning_de":"Qualität und Ausführung eines Torschussversuchs","meaning":"Qualität und Ausführung eines Torschussversuchs"},{"term":"Progressiver Pass","meaning_de":"Pass, der den Ball deutlich Richtung gegnerisches Tor voranbringt; Definition je Datenanbieter prüfen","meaning":"Pass, der den Ball deutlich Richtung gegnerisches Tor voranbringt; Definition je Datenanbieter prüfen"},{"term":"Gegenpressing","meaning_de":"unmittelbarer Rückeroberungsversuch nach Ballverlust","meaning":"unmittelbarer Rückeroberungsversuch nach Ballverlust"},{"term":"Raumdeckung","meaning_de":"Verteidigung eines Raums statt ausschließlicher Manndeckung","meaning":"Verteidigung eines Raums statt ausschließlicher Manndeckung"},{"term":"Belastbarkeit","meaning_de":"Fähigkeit, Trainings- und Spielbelastung über Zeit zu bewältigen","meaning":"Fähigkeit, Trainings- und Spielbelastung über Zeit zu bewältigen"},{"term":"Entscheidungsfindung","meaning_de":"Qualität der Wahl einer Handlung unter Spielsituationsdruck","meaning":"Qualität der Wahl einer Handlung unter Spielsituationsdruck"}],"examples":[],"common_errors":["Metriken ohne Definition oder Bezugsgröße vergleichen.","Potenzial als sichere Zukunftsaussage darstellen.","Taktische Begriffe ohne Positions- und Spielkontext übersetzen."],"learning_objectives":["Scoutingbegriffe fachlich einordnen","Statistische und taktische Aussagen trennen","Unsicherheit und Datenherkunft offenlegen"]}'::jsonb,ARRAY['football','scouting','tactics','analytics','terminology','player analysis'],'specialist','active','original_authored','messinho_linguistic_v2'),
('de.conversation.repair_clarification',1,'de','conversation','Dialogsteuerung und Klärung','Rückfragen, Reparatur und Verständnissicherung – Deutsch','{"explanation":"Bei unklarer Referenz, fehlendem Kontext oder widersprüchlicher Aussage gezielt nachfragen. Die Rückfrage soll nur die fehlende Information erheben. Bei Korrekturen Original und Vorschlag getrennt zeigen; bei Übersetzungen Register und Zielgruppe berücksichtigen.","examples":[{"text":"Meinst du seine aktuelle Saison oder seine gesamte Laufbahn?","intent":"zeitlichen Bezugsrahmen klären"},{"text":"Soll die Übersetzung formell oder umgangssprachlich klingen?","intent":"Register klären"},{"text":"Ich kann das so verstehen: ... Ist das gemeint?","intent":"Interpretation transparent bestätigen"}],"common_errors":["Bei Mehrdeutigkeit nicht raten.","Nicht mehrere unnötige Rückfragen auf einmal stellen.","Originalaussage bei einer Korrektur nicht stillschweigend ersetzen."],"learning_objectives":["Fehlenden Kontext gezielt erfragen","Missverständnisse transparent reparieren","Original und Interpretation unterscheiden"]}'::jsonb,ARRAY['conversation','clarification','repair','dialogue','context'],'advanced','active','original_authored','messinho_linguistic_v2'),
('en.grammar.complex_structures',1,'en','grammar','Komplexe Satzstrukturen','Satzstruktur und typische Fehler – English','{"explanation":"English clauses commonly use subject–verb–object order. Auxiliary verbs carry tense, negation and question formation. Distinguish past simple for completed events in a finished past time from present perfect for past events connected to the present. Modals express ability, probability, obligation or advice and are not interchangeable.","examples":[{"text":"The scout watched the player yesterday.","note":"Past simple with a finished time reference."},{"text":"The player has improved this season.","note":"Present perfect connects development to the current season."},{"text":"Could the player adapt to a higher league?","note":"Modal could softens a question and expresses possibility."}],"common_errors":["Do not use present perfect with a finished-time adverb such as yesterday.","Do not omit do-support in ordinary present simple questions and negatives.","Do not translate German modal verbs one-to-one without context."],"learning_objectives":["Satzstruktur korrekt erkennen","Zeit- und Aspektformen kontextbezogen unterscheiden","Negation und Einschränkungen vollständig erhalten"],"review_questions":["Welche Information trägt die Verbform?","Welche Satzteile gehören zusammen?","Welche Bedeutung ändert sich bei anderer Wortstellung?"],"grammar_notes":["Beispiele sind original formuliert und illustrativ, keine vollständige Grammatik."]}'::jsonb,ARRAY['grammar','syntax','word order','tense','negation','sentence structure','scouting'],'intermediate','active','original_authored','messinho_linguistic_v2'),
('en.pragmatics.intent_register',1,'en','pragmatics','Gesprächsabsicht und Register','Höflichkeit, Unsicherheit und Gesprächsnuancen – English','{"explanation":"Hedges such as perhaps, likely, rather, still and not yet qualify certainty. Could you and would you mind often express polite requests. Understatement and indirect disagreement are common; preserve the speaker''s degree of certainty.","examples":[{"text":"He is promising, but not quite ready yet.","intent":"positive assessment with qualification"},{"text":"Would you mind checking the report?","intent":"polite request"},{"text":"That may prove difficult.","intent":"qualified forecast, not certainty"}],"common_errors":["Höfliche Bitte nicht als Befehl interpretieren.","Unsicherheit nicht in Gewissheit umwandeln.","Verneinung, Einschränkung und Kontrast nicht entfernen."],"learning_objectives":["Wörtliche Bedeutung und Gesprächsabsicht unterscheiden","Grad der Gewissheit bewahren","Register und Höflichkeit berücksichtigen"]}'::jsonb,ARRAY['pragmatics','politeness','intent','uncertainty','negation','register'],'advanced','active','original_authored','messinho_linguistic_v2'),
('en.lexicon.football_scouting',1,'en','lexicon','Fußball- und Scoutingterminologie','Fußballbegriffe im Kontext – English','{"explanation":"Scouting terms are context-dependent. Output is not the same as underlying performance; potential is not a guaranteed forecast. Metrics require a provider definition, denominator, competition and time window.","terms":[{"term":"Finishing","meaning_de":"quality and execution of a shot attempt","meaning":"quality and execution of a shot attempt"},{"term":"Progressive pass","meaning_de":"a pass that advances the ball materially toward the opponent''s goal; verify provider definition","meaning":"a pass that advances the ball materially toward the opponent''s goal; verify provider definition"},{"term":"Counter-press","meaning_de":"immediate attempt to regain possession after losing the ball","meaning":"immediate attempt to regain possession after losing the ball"},{"term":"Cover shadow","meaning_de":"positioning that blocks a passing lane while pressing","meaning":"positioning that blocks a passing lane while pressing"},{"term":"Availability","meaning_de":"ability to be selectable and participate, interpreted with injury and selection context","meaning":"ability to be selectable and participate, interpreted with injury and selection context"},{"term":"Decision-making","meaning_de":"quality of action selection under match pressure","meaning":"quality of action selection under match pressure"}],"examples":[],"common_errors":["Metriken ohne Definition oder Bezugsgröße vergleichen.","Potenzial als sichere Zukunftsaussage darstellen.","Taktische Begriffe ohne Positions- und Spielkontext übersetzen."],"learning_objectives":["Scoutingbegriffe fachlich einordnen","Statistische und taktische Aussagen trennen","Unsicherheit und Datenherkunft offenlegen"]}'::jsonb,ARRAY['football','scouting','tactics','analytics','terminology','player analysis'],'specialist','active','original_authored','messinho_linguistic_v2'),
('en.conversation.repair_clarification',1,'en','conversation','Dialogsteuerung und Klärung','Rückfragen, Reparatur und Verständnissicherung – English','{"explanation":"When a reference, timeframe or intended register is unclear, ask one focused question. Separate original text from corrections. Translation choices should reflect audience, formality and domain; never silently invent missing context.","examples":[{"text":"Do you mean this season or his whole career?","intent":"clarify timeframe"},{"text":"Should this sound formal or conversational?","intent":"clarify register"},{"text":"I understand this as ... Is that what you mean?","intent":"confirm interpretation transparently"}],"common_errors":["Bei Mehrdeutigkeit nicht raten.","Nicht mehrere unnötige Rückfragen auf einmal stellen.","Originalaussage bei einer Korrektur nicht stillschweigend ersetzen."],"learning_objectives":["Fehlenden Kontext gezielt erfragen","Missverständnisse transparent reparieren","Original und Interpretation unterscheiden"]}'::jsonb,ARRAY['conversation','clarification','repair','dialogue','context'],'advanced','active','original_authored','messinho_linguistic_v2'),
('fr.grammar.complex_structures',1,'fr','grammar','Komplexe Satzstrukturen','Satzstruktur und typische Fehler – Français','{"explanation":"La phrase déclarative suit généralement sujet–verbe–complément. Les pronoms compléments se placent souvent avant le verbe. Le passé composé présente un événement accompli; l’imparfait décrit souvent un arrière-plan, une habitude ou une situation en cours. L’accord du participe passé dépend de l’auxiliaire et, dans certains cas, de la position du complément.","examples":[{"text":"Le recruteur a observé le joueur.","note":"Passé composé pour un événement achevé."},{"text":"Le joueur progressait chaque semaine.","note":"Imparfait pour une évolution habituelle dans le passé."},{"text":"Je l’ai vu jouer.","note":"Le pronom complément précède l’auxiliaire."}],"common_errors":["Ne pas placer systématiquement le pronom complément après le verbe conjugué.","Ne pas confondre passé composé et imparfait.","Ne pas omettre les accords pertinents."],"learning_objectives":["Satzstruktur korrekt erkennen","Zeit- und Aspektformen kontextbezogen unterscheiden","Negation und Einschränkungen vollständig erhalten"],"review_questions":["Welche Information trägt die Verbform?","Welche Satzteile gehören zusammen?","Welche Bedeutung ändert sich bei anderer Wortstellung?"],"grammar_notes":["Beispiele sind original formuliert und illustrativ, keine vollständige Grammatik."]}'::jsonb,ARRAY['grammar','syntax','word order','tense','negation','sentence structure','scouting'],'intermediate','active','original_authored','messinho_linguistic_v2'),
('fr.pragmatics.intent_register',1,'fr','pragmatics','Gesprächsabsicht und Register','Höflichkeit, Unsicherheit und Gesprächsnuancen – Français','{"explanation":"Le registre, le vouvoiement, les atténuateurs et la formulation indirecte portent une partie du sens. Des expressions comme peut-être, plutôt, quand même et pas encore nuancent l’évaluation. Une question polie peut fonctionner comme une demande.","examples":[{"text":"Il est prometteur, mais pas encore prêt.","intent":"évaluation positive nuancée"},{"text":"Pourriez-vous vérifier le rapport ?","intent":"demande polie"},{"text":"Cela risque d’être difficile.","intent":"prévision prudente"}],"common_errors":["Höfliche Bitte nicht als Befehl interpretieren.","Unsicherheit nicht in Gewissheit umwandeln.","Verneinung, Einschränkung und Kontrast nicht entfernen."],"learning_objectives":["Wörtliche Bedeutung und Gesprächsabsicht unterscheiden","Grad der Gewissheit bewahren","Register und Höflichkeit berücksichtigen"]}'::jsonb,ARRAY['pragmatics','politeness','intent','uncertainty','negation','register'],'advanced','active','original_authored','messinho_linguistic_v2'),
('fr.lexicon.football_scouting',1,'fr','lexicon','Fußball- und Scoutingterminologie','Fußballbegriffe im Kontext – Français','{"explanation":"Les termes de recrutement doivent être interprétés dans leur contexte tactique et statistique. Une statistique dépend de sa définition, de son dénominateur, de la compétition et de la période. Le potentiel n’est jamais une certitude.","terms":[{"term":"Finition","meaning_de":"qualité et exécution d’une tentative de tir","meaning":"qualité et exécution d’une tentative de tir"},{"term":"Passe progressive","meaning_de":"passe qui fait avancer le ballon vers le but adverse; vérifier la définition du fournisseur","meaning":"passe qui fait avancer le ballon vers le but adverse; vérifier la définition du fournisseur"},{"term":"Contre-pressing","meaning_de":"tentative immédiate de récupération après la perte du ballon","meaning":"tentative immédiate de récupération après la perte du ballon"},{"term":"Jeu entre les lignes","meaning_de":"occupation et utilisation des espaces entre les lignes adverses","meaning":"occupation et utilisation des espaces entre les lignes adverses"},{"term":"Disponibilité","meaning_de":"capacité à être sélectionnable, à interpréter avec le contexte médical et sportif","meaning":"capacité à être sélectionnable, à interpréter avec le contexte médical et sportif"},{"term":"Prise de décision","meaning_de":"qualité du choix d’action sous pression","meaning":"qualité du choix d’action sous pression"}],"examples":[],"common_errors":["Metriken ohne Definition oder Bezugsgröße vergleichen.","Potenzial als sichere Zukunftsaussage darstellen.","Taktische Begriffe ohne Positions- und Spielkontext übersetzen."],"learning_objectives":["Scoutingbegriffe fachlich einordnen","Statistische und taktische Aussagen trennen","Unsicherheit und Datenherkunft offenlegen"]}'::jsonb,ARRAY['football','scouting','tactics','analytics','terminology','player analysis'],'specialist','active','original_authored','messinho_linguistic_v2'),
('fr.conversation.repair_clarification',1,'fr','conversation','Dialogsteuerung und Klärung','Rückfragen, Reparatur und Verständnissicherung – Français','{"explanation":"En cas de référence, de période ou de registre ambigu, poser une seule question ciblée. Distinguer le texte original de la correction. Adapter la traduction au public et au domaine sans inventer le contexte manquant.","examples":[{"text":"Parlez-vous de cette saison ou de toute sa carrière ?","intent":"préciser la période"},{"text":"Souhaitez-vous un ton formel ou familier ?","intent":"préciser le registre"},{"text":"Je comprends votre phrase ainsi : ... Est-ce bien cela ?","intent":"confirmer l’interprétation"}],"common_errors":["Bei Mehrdeutigkeit nicht raten.","Nicht mehrere unnötige Rückfragen auf einmal stellen.","Originalaussage bei einer Korrektur nicht stillschweigend ersetzen."],"learning_objectives":["Fehlenden Kontext gezielt erfragen","Missverständnisse transparent reparieren","Original und Interpretation unterscheiden"]}'::jsonb,ARRAY['conversation','clarification','repair','dialogue','context'],'advanced','active','original_authored','messinho_linguistic_v2'),
('ar.grammar.complex_structures',1,'ar','grammar','Komplexe Satzstrukturen','Satzstruktur und typische Fehler – العربية الفصحى','{"explanation":"تُبنى الجملة العربية غالبًا على نمط الجملة الاسمية أو الفعلية. يتغير ترتيب الفاعل والفعل بحسب البنية والتركيز. تتأثر الكلمات بالإعراب، والتذكير والتأنيث، والإفراد والتثنية والجمع. يجب التمييز بين الجذر والوزن الصرفي، وعدم افتراض أن كل صيغة مشتقة تحمل المعنى نفسه.","examples":[{"text":"يحلّل الكشاف أداء اللاعب.","note":"جملة فعلية: فعل ثم فاعل ثم مفعول به."},{"text":"اللاعبُ سريعٌ.","note":"جملة اسمية تصف اللاعب."},{"text":"لم يشارك اللاعب أمس.","note":"النفي بـ لم يرتبط بالفعل المضارع ويجزم الفعل."}],"common_errors":["لا تُحذف علامات النفي عند الترجمة.","لا يُفترض أن ترتيب الكلمات ثابت في كل الجمل.","يجب مراعاة المطابقة بين الصفة والموصوف."],"learning_objectives":["Satzstruktur korrekt erkennen","Zeit- und Aspektformen kontextbezogen unterscheiden","Negation und Einschränkungen vollständig erhalten"],"review_questions":["Welche Information trägt die Verbform?","Welche Satzteile gehören zusammen?","Welche Bedeutung ändert sich bei anderer Wortstellung?"],"grammar_notes":["Beispiele sind original formuliert und illustrativ, keine vollständige Grammatik."]}'::jsonb,ARRAY['grammar','syntax','word order','tense','negation','sentence structure','scouting'],'intermediate','active','original_authored','messinho_linguistic_v2'),
('ar.pragmatics.intent_register',1,'ar','pragmatics','Gesprächsabsicht und Register','Höflichkeit, Unsicherheit und Gesprächsnuancen – العربية الفصحى','{"explanation":"يجب التمييز بين المعنى الحرفي والمقصد التداولي. ألفاظ مثل ربما، قد، ليس بعد، مع ذلك، ومن فضلك تؤثر في درجة اليقين والتهذيب. قد تأتي صيغة السؤال بقصد الطلب أو الاستئذان، لا لطلب معلومة فقط.","examples":[{"text":"اللاعب واعد، لكنه ليس جاهزًا بعد.","intent":"تقييم إيجابي مع تحفظ"},{"text":"هل يمكنك مراجعة التقرير من فضلك؟","intent":"طلب مهذب"},{"text":"قد يكون ذلك صعبًا.","intent":"توقع احتمالي لا يقين"}],"common_errors":["Höfliche Bitte nicht als Befehl interpretieren.","Unsicherheit nicht in Gewissheit umwandeln.","Verneinung, Einschränkung und Kontrast nicht entfernen."],"learning_objectives":["Wörtliche Bedeutung und Gesprächsabsicht unterscheiden","Grad der Gewissheit bewahren","Register und Höflichkeit berücksichtigen"]}'::jsonb,ARRAY['pragmatics','politeness','intent','uncertainty','negation','register'],'advanced','active','original_authored','messinho_linguistic_v2'),
('ar.lexicon.football_scouting',1,'ar','lexicon','Fußball- und Scoutingterminologie','Fußballbegriffe im Kontext – العربية الفصحى','{"explanation":"يجب تفسير مصطلحات الاستكشاف ضمن السياق التكتيكي والإحصائي. لا تعني الأرقام وحدها جودة الأداء، ولا يمثل التطور المتوقع ضمانًا للمستقبل. يجب التحقق من تعريف المؤشر ومصدره والفترة الزمنية.","terms":[{"term":"الإنهاء","meaning_de":"جودة تنفيذ محاولة التسديد","meaning":"جودة تنفيذ محاولة التسديد"},{"term":"التمرير التقدمي","meaning_de":"تمريرة تدفع الكرة إلى الأمام باتجاه مرمى المنافس؛ يجب التحقق من تعريف مزود البيانات","meaning":"تمريرة تدفع الكرة إلى الأمام باتجاه مرمى المنافس؛ يجب التحقق من تعريف مزود البيانات"},{"term":"الضغط العكسي","meaning_de":"محاولة استرجاع الكرة مباشرة بعد فقدانها","meaning":"محاولة استرجاع الكرة مباشرة بعد فقدانها"},{"term":"اللعب بين الخطوط","meaning_de":"استغلال المساحات بين خطوط المنافس","meaning":"استغلال المساحات بين خطوط المنافس"},{"term":"الجاهزية للمشاركة","meaning_de":"إمكانية اختيار اللاعب ومشاركته مع مراعاة السياق الرياضي والصحي","meaning":"إمكانية اختيار اللاعب ومشاركته مع مراعاة السياق الرياضي والصحي"},{"term":"اتخاذ القرار","meaning_de":"جودة اختيار التصرف المناسب تحت ضغط المباراة","meaning":"جودة اختيار التصرف المناسب تحت ضغط المباراة"}],"examples":[],"common_errors":["Metriken ohne Definition oder Bezugsgröße vergleichen.","Potenzial als sichere Zukunftsaussage darstellen.","Taktische Begriffe ohne Positions- und Spielkontext übersetzen."],"learning_objectives":["Scoutingbegriffe fachlich einordnen","Statistische und taktische Aussagen trennen","Unsicherheit und Datenherkunft offenlegen"]}'::jsonb,ARRAY['football','scouting','tactics','analytics','terminology','player analysis'],'specialist','active','original_authored','messinho_linguistic_v2'),
('ar.conversation.repair_clarification',1,'ar','conversation','Dialogsteuerung und Klärung','Rückfragen, Reparatur und Verständnissicherung – العربية الفصحى','{"explanation":"عند غموض المرجع أو الزمن أو مستوى اللغة، ينبغي طرح سؤال واحد محدد. يجب فصل النص الأصلي عن التصحيح، ومراعاة الجمهور والسياق عند الترجمة دون اختلاق معلومات غير موجودة.","examples":[{"text":"هل تقصد هذا الموسم أم مسيرته كلها؟","intent":"تحديد الفترة الزمنية"},{"text":"هل تريد صياغة رسمية أم محادثة يومية؟","intent":"تحديد مستوى اللغة"},{"text":"أفهم كلامك على النحو التالي: ... هل هذا قصدك؟","intent":"تأكيد الفهم بوضوح"}],"common_errors":["Bei Mehrdeutigkeit nicht raten.","Nicht mehrere unnötige Rückfragen auf einmal stellen.","Originalaussage bei einer Korrektur nicht stillschweigend ersetzen."],"learning_objectives":["Fehlenden Kontext gezielt erfragen","Missverständnisse transparent reparieren","Original und Interpretation unterscheiden"]}'::jsonb,ARRAY['conversation','clarification','repair','dialogue','context'],'advanced','active','original_authored','messinho_linguistic_v2'),
('ar-tn.grammar.complex_structures',1,'ar-tn','grammar','Komplexe Satzstrukturen','Satzstruktur und typische Fehler – التونسية / Derja','{"explanation":"التونسية الدارجة لها تنوع جهوي وكتابي، ولا توجد كتابة لاتينية موحدة تمامًا. النفي الشائع يحيط بالفعل بصيغ مثل ما...ش، لكن الاستعمال يتغير حسب الزمن والفعل والمنطقة. الضمائر واللواحق قد تندمج مع الفعل أو الاسم. يجب الحفاظ على الفرق بين الدارجة والفصحى وعدم تحويل الدارجة آليًا إلى فصحى دون طلب.","examples":[{"text":"ما فهمتش كلامك.","note":"نفي تونسي شائع بصيغة ما...ش."},{"text":"نحب نشوف اللاعب هذا.","note":"تعبير عن الرغبة مع إشارة قريبة."},{"text":"اللاعب هذا ينجم يتطور.","note":"ينجم قد يدل على القدرة أو الإمكانية حسب السياق."}],"common_errors":["لا تُعامل Arabizi كتهجئة معيارية واحدة.","لا تُحوّل كل كلمة تونسية إلى مقابل فصيح دون فهم السياق.","لا تعتبر ما...ش قاعدة مطلقة لكل صيغة أو منطقة."],"learning_objectives":["Satzstruktur korrekt erkennen","Zeit- und Aspektformen kontextbezogen unterscheiden","Negation und Einschränkungen vollständig erhalten"],"review_questions":["Welche Information trägt die Verbform?","Welche Satzteile gehören zusammen?","Welche Bedeutung ändert sich bei anderer Wortstellung?"],"grammar_notes":["Beispiele sind original formuliert und illustrativ, keine vollständige Grammatik."]}'::jsonb,ARRAY['grammar','syntax','word order','tense','negation','sentence structure','scouting'],'intermediate','active','original_authored','messinho_linguistic_v2'),
('ar-tn.pragmatics.intent_register',1,'ar-tn','pragmatics','Gesprächsabsicht und Register','Höflichkeit, Unsicherheit und Gesprächsnuancen – التونسية / Derja','{"explanation":"في الدارجة التونسية، النبرة والسياق وكلمات مثل يمكن، ياسر، أما، موش، مازالش وعيشك تنقل درجة اليقين واللطف. السؤال ينجم يكون طلبًا غير مباشر. يلزم الحفاظ على النفي والتحفظ وما نزيدوش معنى موش موجود.","examples":[{"text":"اللاعب باهي، أما مازال موش حاضر.","intent":"تقييم إيجابي مع تحفظ"},{"text":"تنجم تشوف التقرير عيشك؟","intent":"طلب مهذب"},{"text":"يمكن يتحسن مع الوقت.","intent":"احتمال وليس تأكيدًا"}],"common_errors":["Höfliche Bitte nicht als Befehl interpretieren.","Unsicherheit nicht in Gewissheit umwandeln.","Verneinung, Einschränkung und Kontrast nicht entfernen."],"learning_objectives":["Wörtliche Bedeutung und Gesprächsabsicht unterscheiden","Grad der Gewissheit bewahren","Register und Höflichkeit berücksichtigen"]}'::jsonb,ARRAY['pragmatics','politeness','intent','uncertainty','negation','register'],'advanced','active','original_authored','messinho_linguistic_v2'),
('ar-tn.lexicon.football_scouting',1,'ar-tn','lexicon','Fußball- und Scoutingterminologie','Fußballbegriffe im Kontext – التونسية / Derja','{"explanation":"مصطلحات السكوتينغ تتفهم حسب الخطة والمركز والمستوى. الإحصائيات يلزمها مصدر وتعريف وفترة واضحة. الإمكانيات متاع اللاعب ما تعنيش ضمان النجاح، والقرار الفني يلزم يتقارن بدور اللاعب في الفريق.","terms":[{"term":"finition / الإنهاء","meaning_de":"كيفاش اللاعب يكمل الهجمة بالتسديدة","meaning":"كيفاش اللاعب يكمل الهجمة بالتسديدة"},{"term":"progressive pass","meaning_de":"باس يقدّم اللعب لقدّام؛ تعريف الإحصائية يختلف حسب المزوّد","meaning":"باس يقدّم اللعب لقدّام؛ تعريف الإحصائية يختلف حسب المزوّد"},{"term":"contre-pressing","meaning_de":"ضغط مباشر بعد خسارة الكرة باش الفريق يرجّعها","meaning":"ضغط مباشر بعد خسارة الكرة باش الفريق يرجّعها"},{"term":"entre les lignes","meaning_de":"التمركز واستغلال المساحات بين خطوط المنافس","meaning":"التمركز واستغلال المساحات بين خطوط المنافس"},{"term":"disponibilité","meaning_de":"قدرة اللاعب يكون حاضر للاختيار والمشاركة حسب السياق","meaning":"قدرة اللاعب يكون حاضر للاختيار والمشاركة حسب السياق"},{"term":"prise de décision","meaning_de":"كيفاش يختار الحل المناسب تحت ضغط اللعب","meaning":"كيفاش يختار الحل المناسب تحت ضغط اللعب"}],"examples":[],"common_errors":["Metriken ohne Definition oder Bezugsgröße vergleichen.","Potenzial als sichere Zukunftsaussage darstellen.","Taktische Begriffe ohne Positions- und Spielkontext übersetzen."],"learning_objectives":["Scoutingbegriffe fachlich einordnen","Statistische und taktische Aussagen trennen","Unsicherheit und Datenherkunft offenlegen"]}'::jsonb,ARRAY['football','scouting','tactics','analytics','terminology','player analysis'],'specialist','active','original_authored','messinho_linguistic_v2'),
('ar-tn.conversation.repair_clarification',1,'ar-tn','conversation','Dialogsteuerung und Klärung','Rückfragen, Reparatur und Verständnissicherung – التونسية / Derja','{"explanation":"كان المرجع ولا الوقت ولا طريقة الكلام موش واضحين، اسأل سؤال واحد محدد. في التصحيح فرّق بين كلام المستخدم والاقتراح. في الترجمة راعي شكون باش يقراها والسياق، وما تزيدش معلومات من عندك.","examples":[{"text":"تقصد الموسم هذا ولا المسيرة الكل؟","intent":"توضيح الفترة"},{"text":"تحبها رسمية ولا كلام يومي؟","intent":"توضيح الأسلوب"},{"text":"فهمتك هكّا: ... هذا قصدك؟","intent":"تأكيد الفهم"}],"common_errors":["Bei Mehrdeutigkeit nicht raten.","Nicht mehrere unnötige Rückfragen auf einmal stellen.","Originalaussage bei einer Korrektur nicht stillschweigend ersetzen."],"learning_objectives":["Fehlenden Kontext gezielt erfragen","Missverständnisse transparent reparieren","Original und Interpretation unterscheiden"]}'::jsonb,ARRAY['conversation','clarification','repair','dialogue','context'],'advanced','active','original_authored','messinho_linguistic_v2'),
('es.grammar.complex_structures',1,'es','grammar','Komplexe Satzstrukturen','Satzstruktur und typische Fehler – Español','{"explanation":"El orden habitual es sujeto–verbo–complemento, aunque el sujeto puede omitirse porque la conjugación verbal aporta información. El pretérito indefinido presenta hechos terminados; el imperfecto describe hábitos, contexto o procesos pasados. El subjuntivo aparece, entre otros contextos, con deseo, duda, valoración y ciertas subordinadas.","examples":[{"text":"El ojeador observó al jugador ayer.","note":"Pretérito indefinido con referencia temporal terminada."},{"text":"Cuando era joven, entrenaba cada día.","note":"Imperfecto para hábito y contexto pasado."},{"text":"Es importante que el jugador mejore.","note":"Subjuntivo tras una valoración."}],"common_errors":["No confundir indefinido e imperfecto.","No añadir siempre un pronombre sujeto explícito.","No sustituir automáticamente el subjuntivo por el indicativo."],"learning_objectives":["Satzstruktur korrekt erkennen","Zeit- und Aspektformen kontextbezogen unterscheiden","Negation und Einschränkungen vollständig erhalten"],"review_questions":["Welche Information trägt die Verbform?","Welche Satzteile gehören zusammen?","Welche Bedeutung ändert sich bei anderer Wortstellung?"],"grammar_notes":["Beispiele sind original formuliert und illustrativ, keine vollständige Grammatik."]}'::jsonb,ARRAY['grammar','syntax','word order','tense','negation','sentence structure','scouting'],'intermediate','active','original_authored','messinho_linguistic_v2'),
('es.pragmatics.intent_register',1,'es','pragmatics','Gesprächsabsicht und Register','Höflichkeit, Unsicherheit und Gesprächsnuancen – Español','{"explanation":"Expresiones como quizá, todavía no, más bien, sin embargo y podría matizan la certeza. Las peticiones indirectas suelen usar podrías o te importaría. Mantén la diferencia entre una posibilidad, una recomendación y una afirmación.","examples":[{"text":"Es prometedor, pero todavía no está listo.","intent":"valoración positiva con reserva"},{"text":"¿Podrías revisar el informe, por favor?","intent":"petición cortés"},{"text":"Podría resultar difícil.","intent":"pronóstico prudente"}],"common_errors":["Höfliche Bitte nicht als Befehl interpretieren.","Unsicherheit nicht in Gewissheit umwandeln.","Verneinung, Einschränkung und Kontrast nicht entfernen."],"learning_objectives":["Wörtliche Bedeutung und Gesprächsabsicht unterscheiden","Grad der Gewissheit bewahren","Register und Höflichkeit berücksichtigen"]}'::jsonb,ARRAY['pragmatics','politeness','intent','uncertainty','negation','register'],'advanced','active','original_authored','messinho_linguistic_v2'),
('es.lexicon.football_scouting',1,'es','lexicon','Fußball- und Scoutingterminologie','Fußballbegriffe im Kontext – Español','{"explanation":"Los términos de scouting dependen del contexto táctico y estadístico. Cada métrica necesita definición, denominador, competición y periodo. El potencial expresa una hipótesis razonada, no una garantía.","terms":[{"term":"Finalización","meaning_de":"calidad y ejecución de un intento de tiro","meaning":"calidad y ejecución de un intento de tiro"},{"term":"Pase progresivo","meaning_de":"pase que acerca el balón a la portería rival; comprobar la definición del proveedor","meaning":"pase que acerca el balón a la portería rival; comprobar la definición del proveedor"},{"term":"Contrapresión","meaning_de":"intento inmediato de recuperar el balón tras perderlo","meaning":"intento inmediato de recuperar el balón tras perderlo"},{"term":"Juego entre líneas","meaning_de":"ocupación y uso de espacios entre líneas rivales","meaning":"ocupación y uso de espacios entre líneas rivales"},{"term":"Disponibilidad","meaning_de":"posibilidad de ser convocado y participar, con contexto deportivo y médico","meaning":"posibilidad de ser convocado y participar, con contexto deportivo y médico"},{"term":"Toma de decisiones","meaning_de":"calidad de la elección de una acción bajo presión","meaning":"calidad de la elección de una acción bajo presión"}],"examples":[],"common_errors":["Metriken ohne Definition oder Bezugsgröße vergleichen.","Potenzial als sichere Zukunftsaussage darstellen.","Taktische Begriffe ohne Positions- und Spielkontext übersetzen."],"learning_objectives":["Scoutingbegriffe fachlich einordnen","Statistische und taktische Aussagen trennen","Unsicherheit und Datenherkunft offenlegen"]}'::jsonb,ARRAY['football','scouting','tactics','analytics','terminology','player analysis'],'specialist','active','original_authored','messinho_linguistic_v2'),
('es.conversation.repair_clarification',1,'es','conversation','Dialogsteuerung und Klärung','Rückfragen, Reparatur und Verständnissicherung – Español','{"explanation":"Si la referencia, el periodo o el registro no están claros, formula una sola pregunta concreta. Separa el original de la corrección y adapta la traducción al público sin inventar contexto.","examples":[{"text":"¿Te refieres a esta temporada o a toda su carrera?","intent":"aclarar el periodo"},{"text":"¿Prefieres un tono formal o coloquial?","intent":"aclarar el registro"},{"text":"Entiendo tu frase así: ... ¿Es eso lo que quieres decir?","intent":"confirmar la interpretación"}],"common_errors":["Bei Mehrdeutigkeit nicht raten.","Nicht mehrere unnötige Rückfragen auf einmal stellen.","Originalaussage bei einer Korrektur nicht stillschweigend ersetzen."],"learning_objectives":["Fehlenden Kontext gezielt erfragen","Missverständnisse transparent reparieren","Original und Interpretation unterscheiden"]}'::jsonb,ARRAY['conversation','clarification','repair','dialogue','context'],'advanced','active','original_authored','messinho_linguistic_v2')
